function resampleProcess(samples, srIn, srOut, method){
  method = method || 'linear';
  var ratio = srOut / srIn;
  var nOut = Math.max(1, Math.round(samples.length * ratio));
  var out = new Array(nOut);
  for(var i=0;i<nOut;i++){
    var pos = i / ratio;
    var i0 = Math.floor(pos);
    if(method==='nearest'){ out[i] = samples[Math.min(i0, samples.length-1)]; }
    else {
      var i1 = Math.min(i0+1, samples.length-1);
      var f = pos - i0;
      if(i0 >= samples.length-1) f = 0;
      out[i] = samples[i0]*(1-f) + samples[i1]*f;
    }
  }
  return out;
}
function resampleAnalyze(samples, srIn, srOut, method){
  var out = resampleProcess(samples, srIn, srOut, method);
  var peak=0,sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { inLength:samples.length, outLength:out.length, ratio:srOut/srIn, peak:peak, rms:Math.sqrt(sum/out.length) };
}

var EXPORTS={resampleProcess:resampleProcess,resampleAnalyze:resampleAnalyze};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ResampleForgePure = EXPORTS; }
